<?php include '_header.php';if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$st=$conn->prepare('DELETE FROM products WHERE id=?');$st->bind_param('i',$id);$st->execute();header('Location: products.php');exit;}$edit=null;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$edit=$conn->query("SELECT * FROM products WHERE id=$id")->fetch_assoc();}if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$name=$_POST['name'];$slug=strtolower(preg_replace('/[^a-z0-9]+/i','-',$name));$cat=(int)$_POST['category_id'];$price=(float)$_POST['price'];$disc=(int)$_POST['discount_percent'];$stock=(int)$_POST['stock'];$desc=$_POST['description'];$feat=isset($_POST['featured'])?1:0;if($id){$st=$conn->prepare('UPDATE products SET category_id=?,name=?,slug=?,description=?,price=?,discount_percent=?,stock=?,featured=? WHERE id=?');$st->bind_param('isssdiiii',$cat,$name,$slug,$desc,$price,$disc,$stock,$feat,$id);}else{$img='default.svg';$st=$conn->prepare('INSERT INTO products(category_id,name,slug,description,price,discount_percent,stock,image,featured) VALUES(?,?,?,?,?,?,?,?,?)');$st->bind_param('isssdiisi',$cat,$name,$slug,$desc,$price,$disc,$stock,$img,$feat);} $st->execute();header('Location: products.php');exit;}$cats=$conn->query('SELECT * FROM categories');?><h1>Manajemen Produk</h1><div class="panel" style="margin-bottom:20px"><h3><?=$edit?'Edit':'Tambah'?> Produk</h3><form method="post"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><div class="search-panel" style="grid-template-columns:2fr 1fr 1fr"><input class="input" name="name" placeholder="Nama produk" value="<?=htmlspecialchars($edit['name']??'')?>" required><select name="category_id"><?php while($c=$cats->fetch_assoc()):?><option value="<?=$c['id']?>" <?=($edit['category_id']??0)==$c['id']?'selected':''?>><?=$c['name']?></option><?php endwhile;?></select><input class="input" type="number" name="price" placeholder="Harga" value="<?=$edit['price']??''?>" required></div><div class="search-panel" style="grid-template-columns:1fr 1fr 1fr"><input class="input" type="number" name="discount_percent" placeholder="Diskon %" value="<?=$edit['discount_percent']??0?>"><input class="input" type="number" name="stock" placeholder="Stok" value="<?=$edit['stock']??0?>"><label><input type="checkbox" name="featured" <?=!empty($edit['featured'])?'checked':''?>> Produk unggulan</label></div><textarea name="description" placeholder="Deskripsi"><?=htmlspecialchars($edit['description']??'')?></textarea><br><br><button class="btn">Simpan Produk</button></form></div><div class="panel table-wrap"><table class="table"><tr><th>Produk</th><th>Harga</th><th>Stok</th><th>Diskon</th><th>Aksi</th></tr><?php $r=$conn->query('SELECT * FROM products ORDER BY id DESC');while($p=$r->fetch_assoc()):?><tr><td><?=htmlspecialchars($p['name'])?></td><td><?=rupiah($p['price'])?></td><td><?=$p['stock']?></td><td><?=$p['discount_percent']?>%</td><td><a href="?edit=<?=$p['id']?>">Edit</a> · <a href="?delete=<?=$p['id']?>" onclick="return confirmDelete()">Hapus</a></td></tr><?php endwhile;?></table></div><?php include '_footer.php';?>
